    const nowMs = MINUTE_START_MS + 60000 + 2600;
    const early = stateAt(nowMs, MINUTE_START_MS, timeline, UNIT_MS, PERIOD_MS);
    const late = stateAt(
      nowMs,
      MINUTE_START_MS + 60000,
      timeline,
      UNIT_MS,
      PERIOD_MS
    );
    expect(late).toEqual(early);
  });
});
