cd /workspaces/morse-sync/public/js/platform && cat > qr-view.js <<'EOF'
const SVG_NS = 'http://www.w3.org/2000/svg';
// 誤り訂正レベルM: 読み取りやすさとモジュールの粗さ(離れて読めること)の釣り合い
const ERROR_CORRECTION_LEVEL = 'M';
// 型番0は、データ量から自動で決める指定
const AUTO_TYPE_NUMBER = 0;
// QRコードの規格が求めるクワイエットゾーン(4モジュール)
const DEFAULT_MARGIN_MODULES = 4;

/**
 * 同梱ライブラリ(public/vendor/qrcode-generator.js)が定義するグローバル関数を返す。
 * @returns {any} qrcode 関数。読み込まれていなければ undefined
 */
function getQrcodeLib() {
  return /** @type {any} */ (globalThis).qrcode;
}

/**
 * URLからQRコードをSVGで生成し、要素の中身を置き換える。
 * SVGは createElementNS で組み立て、文字列をHTMLとして解釈させない。
 *
 * @param {Element} el 描画先の要素
 * @param {string} url QRコードにするURL
 * @param {{ margin?: number }} [options] margin: 余白(モジュール数)
 * @returns {boolean} 描画できたら true
 */
export function renderQr(el, url, options = {}) {
  const marginModules = options.margin ?? DEFAULT_MARGIN_MODULES;
  const qrcodeLib = getQrcodeLib();
  if (typeof qrcodeLib !== 'function') {
    console.error('QRコード生成ライブラリが読み込まれていません');
    el.replaceChildren();
    return false;
  }
  try {
    const qr = qrcodeLib(AUTO_TYPE_NUMBER, ERROR_CORRECTION_LEVEL);
    qr.addData(url, 'Byte');
    qr.make();
    const moduleCount = /** @type {number} */ (qr.getModuleCount());
    const sizeModules = moduleCount + marginModules * 2;

    const pathCommands = [];
    for (let row = 0; row < moduleCount; row += 1) {
      for (let col = 0; col < moduleCount; col += 1) {
        if (qr.isDark(row, col)) {
          pathCommands.push(
            `M${col + marginModules} ${row + marginModules}h1v1h-1z`
          );
        }
      }
    }

    const svg = document.createElementNS(SVG_NS, 'svg');
    svg.setAttribute('viewBox', `0 0 ${sizeModules} ${sizeModules}`);
    svg.setAttribute('shape-rendering', 'crispEdges');
    svg.setAttribute('role', 'img');
    svg.setAttribute('aria-label', url);
    svg.classList.add('qr-svg');

    const background = document.createElementNS(SVG_NS, 'rect');
    background.setAttribute('width', String(sizeModules));
    background.setAttribute('height', String(sizeModules));
    background.setAttribute('fill', '#ffffff');

    const modules = document.createElementNS(SVG_NS, 'path');
    modules.setAttribute('d', pathCommands.join(''));
    modules.setAttribute('fill', '#000000');

    svg.append(background, modules);
    el.replaceChildren(svg);
    return true;
  } catch (error) {
    console.error('QRコードを生成できませんでした', error);
    el.replaceChildren();
    return false;
  }
}
EOF
cat > wake-lock-keeper.js <<'EOF'
/**
 * Screen Wake Lock API で画面のスリープを防ぐ。
 * タブ切替・画面オフで自動的に解除されるため、表示に戻ったら acquire() を呼び直す。
 */
export class WakeLockKeeper {
  /** @type {WakeLockSentinel | null} */
  #sentinel = null;

  /**
   * ブラウザが Screen Wake Lock API に対応しているか判定する。
   * @returns {boolean} 対応していれば true
   */
  static isSupported() {
    return 'wakeLock' in navigator;
  }

  /**
   * スリープ防止を取得する。取得済みで有効なら何もしない。
   * 失敗しても例外を投げない。
   * @returns {Promise<boolean>} 取得できた(有効な)ら true
   */
  async acquire() {
    if (!WakeLockKeeper.isSupported()) return false;
    if (this.#sentinel && !this.#sentinel.released) return true;
    try {
      this.#sentinel = await navigator.wakeLock.request('screen');
      return true;
    } catch (error) {
      console.warn('Wake Lockを取得できませんでした', error);
      this.#sentinel = null;
      return false;
    }
  }

  /**
   * スリープ防止を解除する。失敗しても例外を投げない。
   * @returns {Promise<void>}
   */
  async release() {
    const sentinel = this.#sentinel;
    this.#sentinel = null;
    if (!sentinel || sentinel.released) return;
    try {
      await sentinel.release();
    } catch (error) {
      console.warn('Wake Lockを解除できませんでした', error);
    }
  }
}
EOF
cat > fullscreen-helper.js <<'EOF'
/**
 * 対応ブラウザでのみ要素を全画面表示にする。
 * iPhone の Safari など非対応のブラウザでは何もしない。失敗しても例外を投げない。
 *
 * @param {Element} el 全画面にする要素
 * @returns {Promise<boolean>} 全画面になったら true
 */
export async function enterFullscreen(el) {
  if (!document.fullscreenEnabled || typeof el.requestFullscreen !== 'function') {
    return false;
  }
  if (document.fullscreenElement) return true;
  try {
    await el.requestFullscreen({ navigationUI: 'hide' });
    return true;
  } catch (error) {
    console.warn('全画面表示にできませんでした', error);
    return false;
  }
}

/**
 * 全画面表示を終了する。全画面でなければ何もしない。失敗しても例外を投げない。
 *
 * @returns {Promise<void>}
 */
export async function exitFullscreen() {
  if (!document.fullscreenElement) return;
  try {
    await document.exitFullscreen();
  } catch (error) {
    console.warn('全画面表示を終了できませんでした', error);
  }
}
EOF
cat > share-helper.js <<'EOF'
/**
 * @typedef {'shared' | 'copied' | 'cancelled' | 'failed'} ShareResult
 */

/**
 * URLをクリップボードにコピーする。失敗しても例外を投げない。
 *
 * @param {string} url コピーするURL
 * @returns {Promise<boolean>} コピーできたら true
 */
async function copyToClipboard(url) {
  if (!navigator.clipboard || typeof navigator.clipboard.writeText !== 'function') {
    return false;
  }
  try {
    await navigator.clipboard.writeText(url);
    return true;
  } catch (error) {
    console.warn('クリップボードにコピーできませんでした', error);
    return false;
  }
}

/**
 * URLを共有する。Web Share API があればOSの共有シートを開き、
 * なければ(または共有に失敗したら)クリップボードにコピーする。
 *
 * @param {string} url 共有するURL
 * @returns {Promise<ShareResult>} 共有シートで共有 / コピー / キャンセル / 失敗
 */
export async function shareUrl(url) {
  if (typeof navigator.share === 'function') {
    try {
      await navigator.share({ url });
      return 'shared';
    } catch (error) {
      if (error instanceof DOMException && error.name === 'AbortError') {
        return 'cancelled';
      }
      console.warn('共有シートを開けませんでした', error);
    }
  }
  return (await copyToClipboard(url)) ? 'copied' : 'failed';
}
EOF
