 * 参加画面の下部に出すメニューを作る。点滅は止めずに重ねて表示する。
 *
 * @param {JoinMenuHandlers} handlers 各項目の処理
 * @returns {JoinMenu}
 */
export function createJoinMenu(handlers) {
  /** @type {ReturnType<typeof setTimeout> | undefined} */
  let closeTimerId;

