/* モールスシンク 全画面共通のスタイル
   CSPのため、インラインスタイル・<style> は使わない。動的な色は JS から CSSOM で設定する */

*,
*::before,
*::after {
  box-sizing: border-box;
}

:root {
  --color-bg: #111111;
  --color-surface: #1d1d1d;
  --color-border: #3a3a3a;
  --color-text: #f2f2f2;
  --color-muted: #b0b0b0;
  --color-accent: #ffcc00;
  --color-accent-text: #111111;
  --color-error: #ff8a80;
  --color-warning: #ffd180;
  --radius: 12px;
  --tap-size: 44px;
}

html,
body {
  margin: 0;
  min-height: 100%;
  background: var(--color-bg);
  color: var(--color-text);
  font-family:
    system-ui,
    -apple-system,
    'Hiragino Sans',
    'Noto Sans JP',
    sans-serif;
  font-size: 16px;
  line-height: 1.6;
  -webkit-text-size-adjust: 100%;
}

[hidden] {
  display: none !important;
}

h1 {
  margin: 0 0 4px;
  font-size: 1.5rem;
}

/* ---- 画面共通 ---- */

.screen {
  width: 100%;
  max-width: 640px;
  margin: 0 auto;
  padding: 16px;
}

.screen__header {
  margin-bottom: 16px;
}

.tagline {
  margin: 0;
  color: var(--color-muted);
}

.warning {
  margin: 8px 0 0;
  color: var(--color-warning);
}

.card {
  margin-bottom: 16px;
  padding: 16px;
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
}

.button-row {
  display: flex;
  flex-wrap: wrap;
