  color: #111111;
}

/* ---- 参加画面 ---- */

.join-before {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.pattern-summary {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 4px 12px;
  width: 100%;
  margin: 16px 0;
  text-align: left;
}

.pattern-summary dt {
  color: var(--color-muted);
}

.pattern-summary dd {
  margin: 0;
  word-break: break-all;
}

.pattern-summary__message {
  font-size: 1.25rem;
  font-weight: bold;
}

/* PRD: ボタンの高さ・幅は画面の短辺の30%以上 */
.join-button {
  width: max(60vmin, 200px);
  max-width: 100%;
  height: max(36vmin, 120px);
  min-width: 30vmin;
  min-height: 30vmin;
  border: none;
  border-radius: 24px;
  background: var(--color-accent);
  color: var(--color-accent-text);
  font: inherit;
  font-size: clamp(1.5rem, 7vmin, 3rem);
  font-weight: bold;
  cursor: pointer;
}

/* 点滅用の全画面要素。背景色だけを切り替え、レイアウトを変えない */
.stage {
  position: fixed;
  inset: 0;
  z-index: 10;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: #000000;
  color: #666666;
  cursor: pointer;
  user-select: none;
  -webkit-user-select: none;
  -webkit-tap-highlight-color: transparent;
}

.stage__char {
  position: absolute;
  top: max(8px, env(safe-area-inset-top));
  left: 0;
  right: 0;
  margin: 0;
  font-size: 1.25rem;
  font-weight: bold;
  text-align: center;
}

.stage__countdown {
  margin: 0;
  color: #dddddd;
  font-size: clamp(1.5rem, 8vmin, 3rem);
  font-weight: bold;
}

.stage__hint {
  margin: 8px 0 0;
  color: #999999;
  text-align: center;
}

.stage__paused {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  color: #dddddd;
}

.join-menu {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 20;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  padding: 16px 16px max(16px, env(safe-area-inset-bottom));
  background: rgba(0, 0, 0, 0.85);
  cursor: default;
}

/* ---- 読込エラー ---- */

.error-view {
  text-align: center;
}

.error-view__message {
  margin: 24px 0;
  color: var(--color-error);
  font-size: 1.125rem;
}

