// 配信物(public/)の転送量(gzip後)の合計が上限以内か検査する。
// 会場で大勢が同時に読み込んでも回線が詰まらないようにするため(PRD 非機能要件)。
import { readdirSync, readFileSync } from 'node:fs';
import { join, relative } from 'node:path';
import { gzipSync } from 'node:zlib';

const PUBLIC_DIR = new URL('../public/', import.meta.url).pathname;
const LIMIT_BYTES = 100 * 1024;

/**
 * ディレクトリ以下のファイルのパスをすべて集める。
 * @param {string} dir ディレクトリ
 * @returns {string[]} ファイルのパス
 */
function listFiles(dir) {
  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const path = join(dir, entry.name);
    return entry.isDirectory() ? listFiles(path) : [path];
  });
}

const sizes = listFiles(PUBLIC_DIR).map((path) => ({
  path: relative(PUBLIC_DIR, path),
  gzipBytes: gzipSync(readFileSync(path), { level: 9 }).length,
}));
sizes.sort((a, b) => b.gzipBytes - a.gzipBytes);
const totalBytes = sizes.reduce((sum, file) => sum + file.gzipBytes, 0);

for (const file of sizes) {
  console.log(`${(file.gzipBytes / 1024).toFixed(1).padStart(7)} KB  ${file.path}`);
}
console.log(
  `合計 ${(totalBytes / 1024).toFixed(1)} KB / 上限 ${LIMIT_BYTES / 1024} KB(gzip後)`
);

if (totalBytes > LIMIT_BYTES) {
  console.error('配信物の転送量が上限を超えています');
  process.exit(1);
}
EOF
cat > scripts/serve.js <<'EOF'
// 手動確認用に public/ をローカルで配信する(開発時のみ。配信物には含めない)。
// 使い方: npm run serve [-- ポート番号]
import { createServer } from 'node:http';
import { readFile, stat } from 'node:fs/promises';
import { extname, join, normalize, sep } from 'node:path';

const PUBLIC_DIR = normalize(new URL('../public/', import.meta.url).pathname);
const DEFAULT_PORT = 8080;
const port = Number(process.argv[2] ?? process.env.PORT ?? DEFAULT_PORT);

/** @type {Record<string, string>} */
const CONTENT_TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.json': 'application/json; charset=utf-8',
  '.webmanifest': 'application/manifest+json',
};

/**
 * URLのパスを public/ 内のファイルパスにする。public/ の外を指すなら null。
 * @param {string} urlPath リクエストのパス
 * @returns {string | null} ファイルパス
 */
function resolvePath(urlPath) {
  const decoded = decodeURIComponent(urlPath.split('?')[0]);
  const path = normalize(join(PUBLIC_DIR, decoded));
  return path.startsWith(PUBLIC_DIR) || path + sep === PUBLIC_DIR ? path : null;
}

const server = createServer(async (req, res) => {
  let path = resolvePath(req.url ?? '/');
  try {
    if (path === null) throw new Error('forbidden');
    if ((await stat(path)).isDirectory()) path = join(path, 'index.html');
    const body = await readFile(path);
    res.writeHead(200, {
      'Content-Type':
        CONTENT_TYPES[extname(path)] ?? 'application/octet-stream',
      'Cache-Control': 'no-store',
    });
    res.end(body);
  } catch {
    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
    res.end('Not Found');
  }
});

server.listen(port, () => {
  console.log(`http://localhost:${port}/ で public/ を配信しています`);
});
EOF
cat > .github/workflows/ci.yml <<'EOF'
