cat > /tmp/pw/smoke.js <<'EOF'
const { chromium } = require('playwright');
const { spawn } = require('child_process');
const assert = require('assert');
(async () => {
  const server = spawn('node', ['scripts/serve.js', '8123'], { cwd: '/workspaces/morse-sync' });
  await new Promise((r) => server.stdout.once('data', r));
  const browser = await chromium.launch();
  const ctx = await browser.newContext({ viewport: { width: 360, height: 740 } });
  const page = await ctx.newPage();
  const problems = [];
  page.on('console', (m) => { if (['error'].includes(m.type())) problems.push(m.text()); });
  page.on('pageerror', (e) => problems.push('pageerror ' + e.message));
  const requests = [];
  page.on('request', (r) => requests.push(r.url()));
  const base = 'http://localhost:8123/';
  const log = (...a) => console.log('✔', ...a);

  await page.goto(base);
  await page.waitForSelector('.qr-svg');
  assert.equal(await page.textContent('.code-text'), '・・・ −−− ・・・');
  assert.equal(await page.textContent('.cycle strong'), '8.5秒');
  const url = await page.textContent('.qr-section .share-url');
  assert.equal(url, base + '#v=1&l=en&m=SOS&p=10&u=250&c=ffcc00');
  log('作成画面の初期表示', url);

  await page.fill('#message-input', 'hello world');
  assert.equal(await page.textContent('.cycle strong'), '29.5秒');
  assert.match(await page.textContent('.qr-section .share-url'), /m=HELLO%20WORLD&p=30/);
  log('入力で符号・所要時間・URLが更新');

  await page.fill('#message-input', 'HIあ😀');
  assert.equal(await page.isVisible('.qr-section'), false);
  assert.deepEqual(await page.$$eval('.highlighted mark', (m) => m.map((x) => x.textContent)), ['あ', '😀']);
  assert.equal(await page.textContent('.errors li'), 'この文字は送れません: あ 😀');
  log('対応外の文字: 強調・エラー・QR非表示');

  await page.fill('#message-input', '0'.repeat(50));
  assert.match(await page.textContent('.errors'), /60秒以内に収まりません/);
  assert.match(await page.textContent('.cycle strong'), /秒$/);
  await page.fill('#message-input', 'E');
  await page.fill('#unit-input', '100');
  assert.match(await page.textContent('.errors'), /200〜2000ミリ秒/);
  assert.equal(await page.isVisible('.qr-section'), false);
  await page.fill('#unit-input', '200');
  assert.equal(await page.isVisible('.qr-section'), true);
  log('60秒超・1拍範囲外のエラー');

  await page.fill('#message-input', 'SOS');
  await page.fill('#unit-input', '250');
  await page.waitForTimeout(200);
  await page.click('text=拡大表示');
  await page.waitForSelector('.qr-overlay .qr-svg');
  await page.click('.qr-overlay >> text=閉じる');
  assert.equal(await page.$('.qr-overlay'), null);
  log('拡大表示と閉じる');

  await page.click('text=このパターンで参加');
  await page.waitForSelector('.join-button');
  assert.equal(new URL(page.url()).hash, '#v=1&l=en&m=SOS&p=10&u=250&c=ffcc00');
  const box = await page.$eval('.join-button', (b) => b.getBoundingClientRect().toJSON());
  assert.ok(box.width >= 360 * 0.3 && box.height >= 360 * 0.3, JSON.stringify(box));
  log('参加画面へ遷移、参加ボタンの大きさ', box.width, box.height);

  await page.click('.join-button');
  await page.waitForSelector('.stage:not([hidden])');
  const countdown = await page.textContent('.stage__countdown');
  log('待機中の表示:', JSON.stringify(countdown));
  // 点灯・消灯を Date.now() と照合する(SOS: 0-250ms 点灯、250-500ms 消灯)
  let checked = 0, mismatches = 0;
  const deadline = Date.now() + 12000;
  while (Date.now() < deadline) {
    const r = await page.evaluate(() => new Promise((res) => requestAnimationFrame(() => {
      const t = Date.now() % 10000;
      res({ t, bg: getComputedStyle(document.querySelector('.stage')).backgroundColor, ch: document.querySelector('.stage__char').textContent, cd: document.querySelector('.stage__countdown').textContent });
    })));
    const units = r.t / 250;
    const on = [[0,1],[2,3],[4,5],[8,11],[12,15],[16,19],[22,23],[24,25],[26,27]].some(([s,e]) => units >= s && units < e);
    const nearEdge = [0,1,2,3,4,5,8,11,12,15,16,19,22,23,24,25,26,27].some((b) => Math.abs(units - b) * 250 < 40);
    if (r.cd === '' && !nearEdge) {
      checked++;
      const isOn = r.bg === 'rgb(255, 204, 0)';
      if (isOn !== on) { mismatches++; console.log('mismatch', r); }
    }
    await page.waitForTimeout(37);
  }
  assert.ok(checked > 50, 'checked ' + checked);
  assert.equal(mismatches, 0);
  log(`点灯状態を時刻と照合: ${checked}サンプル、不一致0`);

  await page.mouse.click(180, 300);
  assert.equal(await page.isVisible('.join-menu'), true);
  await page.waitForTimeout(5300);
  assert.equal(await page.isVisible('.join-menu'), false);
  log('メニューは5秒で自動で閉じる');
  await page.mouse.click(180, 300);
  await page.mouse.click(180, 200);
  assert.equal(await page.isVisible('.join-menu'), false);
  log('メニュー外のタップで閉じる');

  await page.mouse.click(180, 300);
  await page.click('text=QRコードを見せる');
  await page.waitForSelector('.qr-overlay .qr-svg');
  await page.click('.qr-overlay >> text=戻る');
  assert.equal(await page.$('.qr-overlay'), null);
  assert.match(await page.textContent('.stage__countdown'), /開始まで あと\d+秒/);
  log('QRコードを見せる → 戻る → 待機中');

  await page.mouse.click(180, 300);
  await page.click('.join-menu >> text=一時停止');
  assert.equal(await page.isVisible('.stage__paused'), true);
  assert.equal(await page.$eval('.stage', (s) => getComputedStyle(s).backgroundColor), 'rgb(0, 0, 0)');
  await page.click('text=再開');
  assert.equal(await page.isVisible('.stage__paused'), false);
  log('一時停止 → 再開');

  await page.goto(base + '#v=1&m=HELLO&p=15');
  await page.waitForSelector('.join-button');
  await page.click('text=パターンを作る');
  await page.waitForSelector('#message-input');
  assert.equal(await page.inputValue('#message-input'), 'HELLO');
  assert.equal(new URL(page.url()).hash, '');
  log('パターンを作る: ハッシュを消して設定を引き継ぐ');

  await page.goto(base + '#v=1&m=HELLO&p=7');
  await page.waitForSelector('.error-view');
  assert.equal(await page.textContent('.error-view__message'), 'QRコードの内容が正しくありません');
  await page.evaluate(() => { location.hash = 'v=2&m=X&p=1'; });
  await page.waitForFunction(() => document.querySelector('.error-view__message')?.textContent.includes('新しいバージョン'));
  await page.evaluate(() => { location.hash = 'v=1&m=%3Cimg%20src%3Dx%3E&p=15'; });
  await page.waitForSelector('.error-view');
  await page.evaluate(() => { location.hash = 'v=1&m=E&p=2&c=00ff00'; });
  await page.waitForSelector('.join-button');
  log('読込エラー / 未知のバージョン / hashchange で再描画');

  await page.setViewportSize({ width: 320, height: 640 });
  await page.goto(base);
  await page.waitForSelector('.qr-svg');
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth > innerWidth);
  assert.equal(overflow, false);
  await page.screenshot({ path: '/tmp/pw/create-320.png', fullPage: true });
  log('幅320pxで横スクロールなし');

  const external = requests.filter((u) => !u.startsWith(base));
  assert.deepEqual(external, []);
  const filtered = problems.filter((p) => !p.includes('Wake Lock'));
  console.log('console errors:', problems);
  assert.deepEqual(filtered, []);
  log('外部通信なし・コンソールエラーなし');
  await browser.close();
  server.kill();
})().catch((e) => { console.error('FAIL', e); process.exit(1); });
EOF
cd /tmp/pw && timeout 120 node smoke.js

