1	/** @typedef {import('./types.js').MorseTable} MorseTable */
2	/** @typedef {import('./types.js').EncodedMessage} EncodedMessage */
3	/** @typedef {import('./types.js').EncodedChar} EncodedChar */
4	
5	const WORD_SEPARATOR = ' ';
6	
7	/**
8	 * 変換表の規則でメッセージを正規化する(大文字化・空白の整理など)。
9	 *
10	 * @param {string} input 入力された文字列
11	 * @param {MorseTable} table 変換表
12	 * @returns {string} 正規化後のメッセージ
13	 */
14	export function normalizeMessage(input, table) {
15	  return table.normalize(input);
16	}
17	
18	/**
19	 * 正規化済みのメッセージを文字ごとの符号に変換し、対応外の文字を集める。
20	 * 文字はコードポイント単位で扱う(絵文字を1文字として報告するため)。
21	 *
22	 * @param {string} normalized 正規化済みのメッセージ
23	 * @param {MorseTable} table 変換表
24	 * @returns {EncodedMessage} 符号化結果
25	 */
26	export function encodeMessage(normalized, table) {
27	  /** @type {EncodedChar[]} */
28	  const chars = [];
29	  /** @type {string[]} */
30	  const unsupported = [];
31	  [...normalized].forEach((char, sourceIndex) => {
32	    if (char === WORD_SEPARATOR) {
33	      chars.push({ char, code: '', sourceIndex });
34	      return;
35	    }
36	    const code = Object.hasOwn(table.codes, char) ? table.codes[char] : null;
37	    if (code === null && !unsupported.includes(char)) {
38	      unsupported.push(char);
39	    }
40	    chars.push({ char, code, sourceIndex });
41	  });
42	  return { chars, unsupported };
43	}
44	
45	/**
46	 * 内部の符号('.' と '-')を画面表示用の記号に置き換える。
47	 *
48	 * @param {string} code 符号 例: '.-'
49	 * @returns {string} 表示用の符号 例: '・−'
50	 */
51	export function formatCode(code) {
52	  return code.replaceAll('.', '・').replaceAll('-', '−');
53	}
54	
55	/**
56	 * 符号化結果全体を画面表示用の文字列にする。
57	 * 文字ごとに空白で区切り、単語の区切りは '/'、対応外の文字は '?' で表す。
58	 *
59	 * @param {EncodedMessage} encoded 符号化結果
60	 * @returns {string} 表示用の文字列 例: '・・・ −−− ・・・'
61	 */
62	export function formatEncodedMessage(encoded) {
63	  return encoded.chars
64	    .map((ch) => {
65	      if (ch.char === WORD_SEPARATOR) return '/';
66	      return ch.code === null ? '?' : formatCode(ch.code);
67	    })
68	    .join(' ');
69	}
