1	/** @typedef {import('./types.js').EncodedMessage} EncodedMessage */
2	/** @typedef {import('./types.js').EncodedChar} EncodedChar */
3	/** @typedef {import('./types.js').Timeline} Timeline */
4	/** @typedef {import('./types.js').OnSegment} OnSegment */
5	
6	// ITU-R M.1677 の拍数の比率
7	const DOT_UNITS = 1;
8	const DASH_UNITS = 3;
9	const INTRA_CHAR_GAP_UNITS = 1;
10	const INTER_CHAR_GAP_UNITS = 3;
11	const WORD_GAP_UNITS = 7;
12	// 周の末尾の区切り。次の周の先頭と続けて読まれないよう、単語間の間隔と同じ長さにする
13	const CYCLE_GAP_UNITS = WORD_GAP_UNITS;
14	
15	/**
16	 * 符号化結果を空白で単語に分ける。符号のない文字(空白・対応外)は含めない。
17	 *
18	 * @param {EncodedChar[]} chars 符号化結果の文字
19	 * @returns {EncodedChar[][]} 単語ごとの文字の並び
20	 */
21	function splitWords(chars) {
22	  /** @type {EncodedChar[][]} */
23	  const words = [];
24	  /** @type {EncodedChar[]} */
25	  let word = [];
26	  for (const ch of chars) {
27	    if (ch.char === ' ') {
28	      if (word.length > 0) words.push(word);
29	      word = [];
30	    } else if (ch.code) {
31	      word.push(ch);
32	    }
33	  }
34	  if (word.length > 0) words.push(word);
35	  return words;
36	}
37	
38	/**
39	 * 符号化結果を、1周分の点灯区間の列に展開する。
40	 * 対応外の文字(符号が null)は無視する。
41	 *
42	 * @param {EncodedMessage} encoded 符号化結果
43	 * @returns {Timeline} 点灯区間の列と1周分の拍数(末尾の区切りを含む)
44	 */
45	export function buildTimeline(encoded) {
46	  /** @type {OnSegment[]} */
47	  const segments = [];
48	  let t = 0;
49	  splitWords(encoded.chars).forEach((word, wordIndex) => {
50	    if (wordIndex > 0) t += WORD_GAP_UNITS;
51	    word.forEach((ch, charPos) => {
52	      if (charPos > 0) t += INTER_CHAR_GAP_UNITS;
53	      [...(ch.code ?? '')].forEach((symbol, symbolPos) => {
54	        if (symbolPos > 0) t += INTRA_CHAR_GAP_UNITS;
55	        const lengthUnits = symbol === '.' ? DOT_UNITS : DASH_UNITS;
56	        segments.push({
57	          startUnit: t,
58	          endUnit: t + lengthUnits,
59	          charIndex: ch.sourceIndex,
60	        });
61	        t += lengthUnits;
62	      });
63	    });
64	  });
65	  return { segments, totalUnits: t + CYCLE_GAP_UNITS };
66	}
67	
68	/**
69	 * 1周分の所要時間を求める。
70	 *
71	 * @param {Timeline} timeline 点灯区間の列
72	 * @param {number} unitMs 1拍の長さ(ミリ秒)
73	 * @returns {number} 1周分の所要時間(ミリ秒、末尾の区切りを含む)
74	 */
75	export function cycleMsOf(timeline, unitMs) {
76	  return timeline.totalUnits * unitMs;
77	}
78	
79	/**
80	 * 周期内の位置(拍)を含む点灯区間を二分探索で探す。
81	 *
82	 * @param {OnSegment[]} segments 点灯区間。開始拍の昇順で重ならないこと
83	 * @param {number} elapsedUnits 周期の開始からの経過拍数(小数可)
84	 * @returns {OnSegment | null} 含む区間。消灯中なら null
85	 */
86	export function findSegment(segments, elapsedUnits) {
87	  let low = 0;
88	  let high = segments.length - 1;
89	  while (low <= high) {
90	    const mid = (low + high) >> 1;
91	    const segment = segments[mid];
92	    if (elapsedUnits < segment.startUnit) {
93	      high = mid - 1;
94	    } else if (elapsedUnits >= segment.endUnit) {
95	      low = mid + 1;
96	    } else {
97	      return segment;
98	    }
99	  }
100	  return null;
101	}
