3	/** @typedef {import('./types.js').Timeline} Timeline */
4	/** @typedef {import('./types.js').PlaybackState} PlaybackState */
5	
6	/**
7	 * 現在時刻を含む周期の開始時刻を求める。
8	 * UNIX時刻0は分の0秒で、周期は60秒の約数なので、どの端末でも同じ時刻になる。
9	 *
10	 * @param {number} nowMs 現在のUNIX時刻(ミリ秒)
11	 * @param {number} periodMs 同期の周期(ミリ秒)
12	 * @returns {number} 周期の開始時刻(ミリ秒)
13	 */
14	export function currentCycleStart(nowMs, periodMs) {
15	  return Math.floor(nowMs / periodMs) * periodMs;
16	}
17	
18	/**
19	 * 次に来る開始時刻を求める。境界ちょうどなら現在時刻をそのまま返す(即開始)。
20	 *
21	 * @param {number} nowMs 現在のUNIX時刻(ミリ秒)
22	 * @param {number} periodMs 同期の周期(ミリ秒)
23	 * @returns {number} 次の開始時刻(ミリ秒)
24	 */
25	export function nextCycleStart(nowMs, periodMs) {
26	  return Math.ceil(nowMs / periodMs) * periodMs;
27	}
28	
29	/**
30	 * ある時刻の再生状態を求める。
31	 * 前回からの経過時間を積み上げず、毎回現在時刻から計算するため、
32	 * フレーム落ちや長時間の動作でも誤差が蓄積しない。
33	 *
34	 * @param {number} nowMs 現在のUNIX時刻(ミリ秒)
35	 * @param {number} firstStartMs 参加後の最初の開始時刻(ミリ秒)
36	 * @param {Timeline} timeline 1周分の点灯区間の列
37	 * @param {number} unitMs 1拍の長さ(ミリ秒)
38	 * @param {number} periodMs 同期の周期(ミリ秒)
39	 * @returns {PlaybackState} 再生状態
40	 */
41	export function stateAt(nowMs, firstStartMs, timeline, unitMs, periodMs) {
42	  if (nowMs < firstStartMs) {
43	    return {
44	      phase: 'waiting',
45	      isOn: false,
46	      charIndex: null,
47	      msToNextStart: firstStartMs - nowMs,
48	    };
49	  }
50	  const cycleStartMs = currentCycleStart(nowMs, periodMs);
51	  const elapsedUnits = (nowMs - cycleStartMs) / unitMs;
52	  const segment = findSegment(timeline.segments, elapsedUnits);
53	  return {
54	    phase: 'playing',
55	    isOn: segment !== null,
56	    charIndex: segment ? segment.charIndex : null,
57	    msToNextStart: cycleStartMs + periodMs - nowMs,
58	  };
59	}
