23	// URLのキー(v l m p u c)はこのファイルの中だけで使う
24	const DIGITS_PATTERN = /^\d+$/;
25	const HEX_COLOR_PATTERN = /^[0-9a-fA-F]{6}$/;
26	
27	/**
28	 * メッセージを正規化・符号化し、文字数と対応文字を検証する。
29	 *
30	 * @param {string} rawMessage 入力またはURLのメッセージ
31	 * @param {MorseTable} table 変換表
32	 * @returns {{ normalized: string, encoded: EncodedMessage, errors: ValidationError[] }}
33	 */
34	function validateMessage(rawMessage, table) {
35	  const normalized = normalizeMessage(rawMessage, table);
36	  const encoded = encodeMessage(normalized, table);
37	  /** @type {ValidationError[]} */
38	  const errors = [];
39	  const length = encoded.chars.length;
40	  if (length === 0) {
41	    errors.push({ code: 'EMPTY_MESSAGE' });
42	  } else if (length > MAX_MESSAGE_LENGTH) {
43	    errors.push({ code: 'MESSAGE_TOO_LONG' });
44	  }
45	  if (encoded.unsupported.length > 0) {
46	    errors.push({
47	      code: 'UNSUPPORTED_CHARS',
48	      detail: encoded.unsupported.join(' '),
49	    });
50	  }
51	  return { normalized, encoded, errors };
52	}
53	
54	/**
55	 * 1拍の長さの文字列を検証して数値にする。
56	 *
57	 * @param {string} rawUnitMs 1拍の長さ(ミリ秒)の文字列
58	 * @returns {number | null} 200〜2000の整数なら数値、それ以外は null
59	 */
60	function parseUnitMs(rawUnitMs) {
61	  const trimmed = rawUnitMs.trim();
62	  if (!DIGITS_PATTERN.test(trimmed)) return null;
63	  const unitMs = Number(trimmed);
64	  return unitMs >= MIN_UNIT_MS && unitMs <= MAX_UNIT_MS ? unitMs : null;
65	}
66	
67	/**
68	 * 点灯色の文字列を検証して小文字の16進6桁にする。
69	 *
70	 * @param {string} rawColor '#'なしの16進6桁
71	 * @returns {string | null} 小文字の16進6桁。不正なら null
72	 */
73	function parseColor(rawColor) {
74	  return HEX_COLOR_PATTERN.test(rawColor) ? rawColor.toLowerCase() : null;
75	}
76	
77	/**
78	 * 点滅パターンをURLのハッシュにする。
79	 * キーの順序を固定し、既定値と同じ任意項目も省略しない
80	 * (同じ設定なら常に同じURL・同じQRコードになるように)。
81	 *
82	 * @param {PatternConfig} config 検証済みの設定
83	 * @returns {string} ハッシュ 例: '#v=1&l=en&m=HELLO&p=15&u=250&c=ffcc00'
84	 */
85	export function toHash(config) {
86	  return (
87	    `#v=${config.version}&l=${config.lang}` +
88	    `&m=${encodeURIComponent(config.message)}` +
89	    `&p=${config.periodSec}&u=${config.unitMs}&c=${config.color}`
90	  );
91	}
92	
93	/**
94	 * 共有URL(QRコードの中身)を作る。
95	 *
96	 * @param {PatternConfig} config 検証済みの設定
97	 * @param {string} baseUrl ページのURL。ハッシュが付いていれば取り除く
98	 * @returns {string} 共有URL
99	 */
100	export function toShareUrl(config, baseUrl) {
101	  return baseUrl.split('#')[0] + toHash(config);
102	}
103	
104	/**
105	 * URLのハッシュを読み込んで検証する(参加画面用)。
106	 * 周期はURLの値をそのまま使い、計算し直さない。
107	 *
108	 * @param {string} hash location.hash の値('#' は付いていてもなくてもよい)
109	 * @returns {ValidationResult} 検証結果
110	 */
111	export function parseHash(hash) {
112	  const params = new URLSearchParams(hash.replace(/^#/, ''));
113	
114	  const version = params.get('v');
115	  if (version === null) {
116	    return { ok: false, errors: [{ code: 'MISSING_FIELD', detail: 'v' }] };
117	  }
118	  if (version !== String(SPEC_VERSION)) {
119	    return {
120	      ok: false,
121	      errors: [{ code: 'UNKNOWN_VERSION', detail: version }],
122	    };
123	  }
124	
125	  /** @type {ValidationError[]} */
126	  const errors = [];
127	
128	  const lang = params.get('l') ?? DEFAULT_LANG;
129	  const table = getTable(lang);
130	  if (table === null) errors.push({ code: 'UNKNOWN_LANG', detail: lang });
131	
132	  const rawMessage = params.get('m');
133	  /** @type {ReturnType<typeof validateMessage> | null} */
134	  let message = null;
135	  if (rawMessage === null) {
136	    errors.push({ code: 'MISSING_FIELD', detail: 'm' });
137	  } else if (table !== null) {
138	    message = validateMessage(rawMessage, table);
139	    errors.push(...message.errors);
140	  }
141	
142	  const unitMs = parseUnitMs(params.get('u') ?? String(DEFAULT_UNIT_MS));
143	  if (unitMs === null) errors.push({ code: 'UNIT_OUT_OF_RANGE' });
144	
145	  const color = parseColor(params.get('c') ?? DEFAULT_COLOR);
146	  if (color === null) errors.push({ code: 'INVALID_COLOR' });
147	
148	  const rawPeriod = params.get('p');
149	  const periodSec =
150	    rawPeriod !== null && DIGITS_PATTERN.test(rawPeriod)
151	      ? Number(rawPeriod)
152	      : null;
153	  if (rawPeriod === null) {
154	    errors.push({ code: 'MISSING_FIELD', detail: 'p' });
155	  } else if (periodSec === null || !isValidPeriod(periodSec, 0)) {
156	    errors.push({ code: 'INVALID_PERIOD', detail: rawPeriod });
157	  }
158	
159	  if (errors.length > 0 || message === null || unitMs === null) {
160	    return { ok: false, errors };
161	  }
162	  const cycleMs = cycleMsOf(buildTimeline(message.encoded), unitMs);
163	  if (
164	    periodSec === null ||
165	    color === null ||
166	    !isValidPeriod(periodSec, cycleMs)
167	  ) {
168	    return {
169	      ok: false,
170	      errors: [{ code: 'INVALID_PERIOD', detail: rawPeriod ?? '' }],
171	    };
172	  }
173	  return {
174	    ok: true,
175	    config: {
176	      version: SPEC_VERSION,
177	      lang: 'en',
178	      message: message.normalized,
179	      periodSec,
180	      unitMs,
181	      color,
182	    },
183	    cycleMs,
184	  };
185	}
186	
187	/**
188	 * 作成画面の入力から点滅パターンを組み立てる。周期はここで自動決定する。
189	 * エラーはすべて同時に返す。
190	 *
191	 * @param {CreateInput} input 入力欄の生の値
192	 * @returns {ValidationResult} 検証結果
193	 */
194	export function buildFromInput(input) {
195	  const table = /** @type {MorseTable} */ (getTable(DEFAULT_LANG));
196	  const message = validateMessage(input.message, table);
197	  /** @type {ValidationError[]} */
198	  const errors = [...message.errors];
199	
200	  const unitMs = parseUnitMs(input.unitMs);
201	  if (unitMs === null) errors.push({ code: 'UNIT_OUT_OF_RANGE' });
202	
203	  const color = parseColor(input.color.replace(/^#/, ''));
204	  if (color === null) errors.push({ code: 'INVALID_COLOR' });
205	
206	  if (message.errors.length > 0 || unitMs === null) {
207	    return { ok: false, errors };
208	  }
209	  const cycleMs = cycleMsOf(buildTimeline(message.encoded), unitMs);
210	  const periodSec = choosePeriod(cycleMs);
211	  if (periodSec === null) errors.push({ code: 'TOO_LONG_FOR_60S' });
212	
213	  if (periodSec === null || color === null) {
214	    return { ok: false, errors };
215	  }
216	  return {
217	    ok: true,
218	    config: {
219	      version: SPEC_VERSION,
220	      lang: 'en',
221	      message: message.normalized,
222	      periodSec,
223	      unitMs,
224	      color,
225	    },
226	    cycleMs,
227	  };
228	}
229	
230	/**
231	 * 作成画面の表示用に、入力の符号化結果と1周分の所要時間を求める。
232	 * 検証エラー(60秒超など)があっても、分かる範囲で表示できるようにする。
233	 *
234	 * @param {CreateInput} input 入力欄の生の値
235	 * @returns {MessagePreview} 表示用の途中結果
236	 */
237	export function previewInput(input) {
238	  const table = /** @type {MorseTable} */ (getTable(DEFAULT_LANG));
239	  const normalized = normalizeMessage(input.message, table);
240	  const encoded = encodeMessage(normalized, table);
241	  const unitMs = parseUnitMs(input.unitMs);
242	  const canMeasure =
243	    encoded.chars.length > 0 &&
244	    encoded.unsupported.length === 0 &&
245	    unitMs !== null;
246	  return {
247	    normalized,
248	    encoded,
249	    cycleMs: canMeasure ? cycleMsOf(buildTimeline(encoded), unitMs) : null,
250	  };
251	}
252	
253	/**
254	 * 検証済みの設定から、1周分の点灯区間の列を作る(参加画面の再生用)。
255	 *
256	 * @param {PatternConfig} config 検証済みの設定
257	 * @returns {import('./types.js').Timeline} 点灯区間の列
258	 */
259	export function buildConfigTimeline(config) {
260	  const table = /** @type {MorseTable} */ (getTable(config.lang));
261	  return buildTimeline(encodeMessage(config.message, table));
262	}
