1	import { nextCycleStart, stateAt } from '../core/sync-clock.js';
2	
3	/** @typedef {import('../core/types.js').Timeline} Timeline */
4	/** @typedef {import('../core/types.js').PlaybackState} PlaybackState */
5	/** @typedef {import('./screen-output.js').Output} Output */
6	
7	/**
8	 * 毎フレーム現在時刻から点灯・消灯を判定し、出力先に通知する。
9	 * 同期の基準は端末間で共有できる壁時計(Date.now)だけを使う。
10	 * performance.now や rAF のタイムスタンプは端末ごとに起点が違うため使わない。
11	 */
12	export class Player {
13	  /** @type {Timeline} */
14	  #timeline;
15	  /** @type {number} */
16	  #unitMs;
17	  /** @type {number} */
18	  #periodMs;
19	  /** @type {Output[]} */
20	  #outputs;
21	  /** @type {((state: PlaybackState) => void)[]} */
22	  #listeners = [];
23	  /** @type {number} */
24	  #firstStartMs = 0;
25	  /** @type {boolean | null} null は「まだ出力に通知していない」 */
26	  #lastIsOn = null;
27	  /** @type {number | null} */
28	  #rafId = null;
29	
30	  /**
31	   * @param {Timeline} timeline 1周分の点灯区間の列
32	   * @param {number} unitMs 1拍の長さ(ミリ秒)
33	   * @param {number} periodSec 同期の周期(秒)。URLの値をそのまま使う
34	   * @param {Output[]} outputs 出力先
35	   */
36	  constructor(timeline, unitMs, periodSec, outputs) {
37	    this.#timeline = timeline;
38	    this.#unitMs = unitMs;
39	    this.#periodMs = periodSec * 1000;
40	    this.#outputs = outputs;
41	  }
42	
43	  /**
44	   * 再生中かどうか。
45	   * @returns {boolean}
46	   */
47	  get isRunning() {
48	    return this.#rafId !== null;
49	  }
50	
51	  /**
52	   * 次の開始時刻を記録し、待機中から再生を始める。再生中なら最初からやり直す。
53	   * 点灯判定は毎回時刻から計算するため、再開しても周りの端末と揃う。
54	   */
55	  start() {
56	    this.stop();
57	    this.#firstStartMs = nextCycleStart(Date.now(), this.#periodMs);
58	    this.#lastIsOn = null;
59	    this.#rafId = requestAnimationFrame(this.#tick);
60	  }
61	
62	  /**
63	   * ループを止め、全出力を消灯する。
64	   */
65	  stop() {
66	    if (this.#rafId !== null) {
67	      cancelAnimationFrame(this.#rafId);
68	      this.#rafId = null;
69	    }
70	    this.#notifyOutputs(false);
71	  }
72	
73	  /**
74	   * 毎フレームの再生状態を受け取るリスナーを登録する(カウントダウン・送信中の文字の表示用)。
75	   * @param {(state: PlaybackState) => void} listener
76	   */
77	  onFrame(listener) {
78	    this.#listeners.push(listener);
79	  }
80	
81	  /**
82	   * 停止し、出力先とリスナーを解放する。
83	   */
84	  dispose() {
85	    this.stop();
86	    this.#listeners = [];
87	    for (const output of this.#outputs) output.dispose();
88	  }
89	
90	  /**
91	   * @param {boolean} isOn
92	   */
93	  #notifyOutputs(isOn) {
94	    if (isOn === this.#lastIsOn) return;
95	    this.#lastIsOn = isOn;
96	    for (const output of this.#outputs) output.setOn(isOn);
97	  }
98	
99	  #tick = () => {
100	    // 次のフレームの予約を先に行い、以降で想定外の例外が出ても点滅を続ける
101	    this.#rafId = requestAnimationFrame(this.#tick);
102	    const state = stateAt(
103	      Date.now(),
104	      this.#firstStartMs,
105	      this.#timeline,
106	      this.#unitMs,
107	      this.#periodMs
108	    );
109	    this.#notifyOutputs(state.isOn);
110	    for (const listener of this.#listeners) listener(state);
111	  };
112	}
