1	/**
2	 * Screen Wake Lock API で画面のスリープを防ぐ。
3	 * タブ切替・画面オフで自動的に解除されるため、表示に戻ったら acquire() を呼び直す。
4	 */
5	export class WakeLockKeeper {
6	  /** @type {WakeLockSentinel | null} */
7	  #sentinel = null;
8	
9	  /**
10	   * ブラウザが Screen Wake Lock API に対応しているか判定する。
11	   * @returns {boolean} 対応していれば true
12	   */
13	  static isSupported() {
14	    return 'wakeLock' in navigator;
15	  }
16	
17	  /**
18	   * スリープ防止を取得する。取得済みで有効なら何もしない。
19	   * 失敗しても例外を投げない。
20	   * @returns {Promise<boolean>} 取得できた(有効な)ら true
21	   */
22	  async acquire() {
23	    if (!WakeLockKeeper.isSupported()) return false;
24	    if (this.#sentinel && !this.#sentinel.released) return true;
25	    try {
26	      this.#sentinel = await navigator.wakeLock.request('screen');
27	      return true;
28	    } catch (error) {
29	      console.warn('Wake Lockを取得できませんでした', error);
30	      this.#sentinel = null;
31	      return false;
32	    }
33	  }
34	
35	  /**
36	   * スリープ防止を解除する。失敗しても例外を投げない。
37	   * @returns {Promise<void>}
38	   */
39	  async release() {
40	    const sentinel = this.#sentinel;
41	    this.#sentinel = null;
42	    if (!sentinel || sentinel.released) return;
43	    try {
44	      await sentinel.release();
45	    } catch (error) {
46	      console.warn('Wake Lockを解除できませんでした', error);
47	    }
48	  }
49	}
