1	/**
2	 * 対応ブラウザでのみ要素を全画面表示にする。
3	 * iPhone の Safari など非対応のブラウザでは何もしない。失敗しても例外を投げない。
4	 *
5	 * @param {Element} el 全画面にする要素
6	 * @returns {Promise<boolean>} 全画面になったら true
7	 */
8	export async function enterFullscreen(el) {
9	  if (
10	    !document.fullscreenEnabled ||
11	    typeof el.requestFullscreen !== 'function'
12	  ) {
13	    return false;
