27	 *
28	 * @returns {Promise<void>}
29	 */
30	export async function exitFullscreen() {
31	  if (!document.fullscreenElement) return;
32	  try {
33	    await document.exitFullscreen();
34	  } catch (error) {
35	    console.warn('全画面表示を終了できませんでした', error);
