3	 */
4	
5	/**
6	 * URLをクリップボードにコピーする。失敗しても例外を投げない。
7	 *
8	 * @param {string} url コピーするURL
9	 * @returns {Promise<boolean>} コピーできたら true
10	 */
11	async function copyToClipboard(url) {
12	  if (
13	    !navigator.clipboard ||
14	    typeof navigator.clipboard.writeText !== 'function'
15	  ) {
16	    return false;
17	  }
18	  try {
19	    await navigator.clipboard.writeText(url);
20	    return true;
21	  } catch (error) {
22	    console.warn('クリップボードにコピーできませんでした', error);
23	    return false;
24	  }
25	}
