27	/**
28	 * URLを共有する。Web Share API があればOSの共有シートを開き、
29	 * なければ(または共有に失敗したら)クリップボードにコピーする。
30	 *
31	 * @param {string} url 共有するURL
32	 * @returns {Promise<ShareResult>} 共有シートで共有 / コピー / キャンセル / 失敗
33	 */
34	export async function shareUrl(url) {
35	  if (typeof navigator.share === 'function') {
36	    try {
37	      await navigator.share({ url });
38	      return 'shared';
39	    } catch (error) {
40	      if (error instanceof DOMException && error.name === 'AbortError') {
41	        return 'cancelled';
42	      }
43	      console.warn('共有シートを開けませんでした', error);
44	    }
45	  }
46	  return (await copyToClipboard(url)) ? 'copied' : 'failed';
47	}
