1	const SVG_NS = 'http://www.w3.org/2000/svg';
2	// 誤り訂正レベルM: 読み取りやすさとモジュールの粗さ(離れて読めること)の釣り合い
3	const ERROR_CORRECTION_LEVEL = 'M';
4	// 型番0は、データ量から自動で決める指定
5	const AUTO_TYPE_NUMBER = 0;
6	// QRコードの規格が求めるクワイエットゾーン(4モジュール)
7	const DEFAULT_MARGIN_MODULES = 4;
8	
9	/**
10	 * 同梱ライブラリ(public/vendor/qrcode-generator.js)が定義するグローバル関数を返す。
11	 * @returns {any} qrcode 関数。読み込まれていなければ undefined
12	 */
13	function getQrcodeLib() {
14	  return /** @type {any} */ (globalThis).qrcode;
15	}
16	
17	/**
18	 * URLからQRコードをSVGで生成し、要素の中身を置き換える。
19	 * SVGは createElementNS で組み立て、文字列をHTMLとして解釈させない。
20	 *
21	 * @param {Element} el 描画先の要素
22	 * @param {string} url QRコードにするURL
23	 * @param {{ margin?: number }} [options] margin: 余白(モジュール数)
24	 * @returns {boolean} 描画できたら true
25	 */
26	export function renderQr(el, url, options = {}) {
27	  const marginModules = options.margin ?? DEFAULT_MARGIN_MODULES;
28	  const qrcodeLib = getQrcodeLib();
29	  if (typeof qrcodeLib !== 'function') {
30	    console.error('QRコード生成ライブラリが読み込まれていません');
31	    el.replaceChildren();
32	    return false;
33	  }
34	  try {
35	    const qr = qrcodeLib(AUTO_TYPE_NUMBER, ERROR_CORRECTION_LEVEL);
36	    qr.addData(url, 'Byte');
37	    qr.make();
38	    const moduleCount = /** @type {number} */ (qr.getModuleCount());
39	    const sizeModules = moduleCount + marginModules * 2;
40	
41	    const pathCommands = [];
42	    for (let row = 0; row < moduleCount; row += 1) {
43	      for (let col = 0; col < moduleCount; col += 1) {
44	        if (qr.isDark(row, col)) {
45	          pathCommands.push(
46	            `M${col + marginModules} ${row + marginModules}h1v1h-1z`
47	          );
48	        }
49	      }
50	    }
51	
52	    const svg = document.createElementNS(SVG_NS, 'svg');
53	    svg.setAttribute('viewBox', `0 0 ${sizeModules} ${sizeModules}`);
54	    svg.setAttribute('shape-rendering', 'crispEdges');
55	    svg.setAttribute('role', 'img');
56	    svg.setAttribute('aria-label', url);
57	    svg.classList.add('qr-svg');
58	
59	    const background = document.createElementNS(SVG_NS, 'rect');
60	    background.setAttribute('width', String(sizeModules));
61	    background.setAttribute('height', String(sizeModules));
62	    background.setAttribute('fill', '#ffffff');
63	
64	    const modules = document.createElementNS(SVG_NS, 'path');
65	    modules.setAttribute('d', pathCommands.join(''));
66	    modules.setAttribute('fill', '#000000');
67	
68	    svg.append(background, modules);
69	    el.replaceChildren(svg);
70	    return true;
71	  } catch (error) {
72	    console.error('QRコードを生成できませんでした', error);
73	    el.replaceChildren();
74	    return false;
75	  }
76	}
