1	import { parseHash, toHash } from '../core/config-codec.js';
2	import { mountCreateScreen } from './create-screen.js';
3	import { mountJoinScreen } from './join-screen.js';
4	import { mountErrorView } from './error-view.js';
5	
6	/** @typedef {import('../core/types.js').PatternConfig} PatternConfig */
7	
8	/**
9	 * 画面遷移の操作。各画面にはこのオブジェクトを渡し、location を直接触らせない。
10	 * @typedef {Object} Navigate
11	 * @property {(config: PatternConfig) => void} toJoin      参加画面へ(ハッシュを設定)
12	 * @property {(config?: PatternConfig) => void} toCreate   作成画面へ(ハッシュを消し、設定を引き継ぐ)
13	 */
14	
15	/**
16	 * location.hash の有無で作成画面・参加画面を切り替え、hashchange を監視する。
17	 *
18	 * @param {HTMLElement} root 画面を表示する要素
19	 */
20	export function startRouter(root) {
21	  /** @type {(() => void) | null} */
22	  let unmount = null;
23	
24	  /** @type {Navigate} */
25	  const navigate = {
26	    toJoin(config) {
27	      const previousHash = location.hash;
28	      // 通常は hashchange を契機に render される。同じハッシュなら発生しないので自分で描き直す
29	      location.hash = toHash(config);
30	      if (location.hash === previousHash) render();
31	    },
32	    toCreate(config) {
33	      // ページを再読み込みせずにハッシュを消す(hashchange は発生しない)
34	      history.pushState(null, '', location.pathname + location.search);
35	      render(config);
36	    },
37	  };
38	
39	  /**
40	   * @param {PatternConfig} [initialConfig] 作成画面に引き継ぐ設定
41	   */
42	  function render(initialConfig) {
43	    unmount?.();
44	    unmount = null;
45	    root.replaceChildren();
46	    window.scrollTo(0, 0);
47	
48	    const hash = location.hash;
49	    if (hash === '' || hash === '#') {
50	      unmount = mountCreateScreen(root, initialConfig, navigate);
51	      return;
52	    }
53	    const result = parseHash(hash);
54	    unmount = result.ok
55	      ? mountJoinScreen(root, result.config, navigate)
56	      : mountErrorView(root, result.errors, navigate);
57	  }
58	
59	  window.addEventListener('hashchange', () => render());
60	  render();
61	}
