1	/**
2	 * @typedef {Object} ElementOptions
3	 * @property {string} [className] class属性
4	 * @property {string} [text] 表示する文字列(textContent で設定する)
5	 * @property {Record<string, string>} [attrs] 属性(style 属性は CSP のため使わない)
6	 * @property {Record<string, EventListener>} [on] イベントリスナー
7	 */
8	
9	/**
10	 * 要素を作る小さな補助関数。文字列は必ず textContent で設定し、HTMLとして解釈させない。
11	 *
12	 * @template {keyof HTMLElementTagNameMap} K
13	 * @param {K} tag タグ名
14	 * @param {ElementOptions} [options] 属性・文字列・イベント
15	 * @param {(Node | null | undefined | false)[]} [children] 子要素(偽値は無視)
16	 * @returns {HTMLElementTagNameMap[K]} 作った要素
17	 */
18	export function createElement(tag, options = {}, children = []) {
19	  const el = document.createElement(tag);
20	  if (options.className) el.className = options.className;
21	  if (options.text !== undefined) el.textContent = options.text;
22	  for (const [name, value] of Object.entries(options.attrs ?? {})) {
23	    el.setAttribute(name, value);
24	  }
25	  for (const [type, listener] of Object.entries(options.on ?? {})) {
26	    el.addEventListener(type, listener);
27	  }
28	  for (const child of children) {
29	    if (child) el.append(child);
30	  }
31	  return el;
32	}
33	
34	/**
35	 * 要素の表示・非表示を切り替える(hidden 属性)。
36	 *
37	 * @param {HTMLElement} el 対象の要素
38	 * @param {boolean} isVisible 表示するなら true
39	 */
40	export function setVisible(el, isVisible) {
41	  el.hidden = !isVisible;
42	}
