192	        playback.charIndex === null ? '' : messageChars[playback.charIndex];
193	    }
194	    if (playback.isOn !== lastIsOn) {
195	      lastIsOn = playback.isOn;
196	      currentChar.style.color = playback.isOn ? CHAR_COLOR_ON : CHAR_COLOR_OFF;
197	    }
198	  }
199	
200	  function startPlayback() {
201	    lastSecondsLeft = -1;
202	    lastCharIndex = null;
203	    lastIsOn = null;
204	    player.start();
205	  }
206	
207	  function stopPlayback() {
208	    player.stop();
209	    countdown.textContent = '';
210	    currentChar.textContent = '';
211	    lastSecondsLeft = -1;
212	    lastCharIndex = null;
213	  }
214	
215	  function join() {
216	    // Wake Lock・全画面はユーザー操作のイベント内で要求する必要があるため、await より前に呼ぶ
217	    wakeLock.acquire().then((isAcquired) => {
218	      setVisible(wakeLockNotice, !isAcquired);
219	    });
220	    enterFullscreen(document.documentElement).then((isEntered) => {
221	      hasEnteredFullscreen = isEntered;
222	    });
223	    state = 'running';
224	    setVisible(beforeView, false);
225	    setVisible(stage, true);
226	    startPlayback();
227	  }
228	
229	  function showQr() {
230	    menu.close();
231	    stopPlayback();
232	    state = 'qr';
233	    // 検証済みの設定から作り直した(正規化済みの)URLで配る
234	    closeQrOverlay = showQrOverlay(root, shareUrlText, {
235	      closeLabel: MESSAGES.back,
236	      onClose: () => {
237	        closeQrOverlay?.();
238	        closeQrOverlay = null;
239	        state = 'running';
240	        startPlayback();
241	      },
242	    });
243	  }
244	
245	  function pause() {
246	    menu.close();
247	    stopPlayback();
248	    state = 'paused';
249	    setVisible(pausedPanel, true);
250	  }
251	
252	  function resume() {
253	    setVisible(pausedPanel, false);
254	    state = 'running';
255	    startPlayback();
256	  }
257	
258	  const handleVisibilityChange = () => {
259	    if (state === 'before') return;
260	    if (document.visibilityState === 'hidden') {
261	      menu.close();
262	      if (state === 'running') stopPlayback();
263	      return;
264	    }
265	    // 画面オフ・タブ切替で Wake Lock は解除されるため、戻ったら取り直す
266	    wakeLock.acquire().then((isAcquired) => {
267	      setVisible(wakeLockNotice, !isAcquired);
268	    });
269	    if (state === 'running') startPlayback();
270	  };
271	  document.addEventListener('visibilitychange', handleVisibilityChange);
272	
273	  root.append(beforeView, stage);
274	
275	  return () => {
276	    document.removeEventListener('visibilitychange', handleVisibilityChange);
277	    player.dispose();
278	    menu.dispose();
279	    closeQrOverlay?.();
280	    wakeLock.release();
281	    if (hasEnteredFullscreen) exitFullscreen();
282	    beforeView.remove();
283	    stage.remove();
284	  };
285	}
