1	import { createElement, setVisible } from './dom.js';
2	import { MESSAGES } from './messages.js';
3	
4	// うっかり触っても点滅が止まらないよう、操作がなければ自動で閉じる
5	const AUTO_CLOSE_MS = 5000;
6	
7	/**
8	 * @typedef {Object} JoinMenuHandlers
9	 * @property {() => void} onShowQr     「QRコードを見せる」
10	 * @property {() => void} onPause      「一時停止」
11	 * @property {() => void} onToggleChar 送信中の文字の表示切替
12	 */
13	
14	/**
15	 * @typedef {Object} JoinMenu
16	 * @property {HTMLElement} element             メニューの要素
17	 * @property {() => void} open                 開く(自動で閉じるタイマーを開始)
18	 * @property {() => void} close                閉じる
19	 * @property {() => boolean} isOpen            開いているか
20	 * @property {(isVisible: boolean) => void} setCharVisible 表示切替ボタンの文言を合わせる
21	 * @property {() => void} dispose              タイマーを止める
22	 */
23	
24	/**
25	 * 参加画面の下部に出すメニューを作る。点滅は止めずに重ねて表示する。
26	 *
27	 * @param {JoinMenuHandlers} handlers 各項目の処理
28	 * @returns {JoinMenu}
29	 */
30	export function createJoinMenu(handlers) {
31	  /** @type {ReturnType<typeof setTimeout> | undefined} */
32	  let closeTimerId;
33	
34	  const restartTimer = () => {
35	    clearTimeout(closeTimerId);
36	    closeTimerId = setTimeout(close, AUTO_CLOSE_MS);
37	  };
38	
39	  const toggleCharButton = createElement('button', {
40	    className: 'button',
41	    attrs: { type: 'button' },
42	    on: { click: () => handlers.onToggleChar() },
43	  });
44	
45	  const element = createElement(
46	    'div',
47	    {
48	      className: 'join-menu',
49	      attrs: { role: 'menu' },
50	      on: {
51	        // メニュー内のタップは「メニュー外のタップ」として扱わない
52	        click: (event) => event.stopPropagation(),
53	        pointerdown: restartTimer,
54	      },
55	    },
56	    [
57	      createElement('button', {
58	        className: 'button button--primary',
59	        text: MESSAGES.showQr,
60	        attrs: { type: 'button', role: 'menuitem' },
61	        on: { click: () => handlers.onShowQr() },
62	      }),
63	      createElement('button', {
64	        className: 'button',
65	        text: MESSAGES.pause,
66	        attrs: { type: 'button', role: 'menuitem' },
67	        on: { click: () => handlers.onPause() },
68	      }),
69	      toggleCharButton,
70	    ]
71	  );
72	  toggleCharButton.setAttribute('role', 'menuitem');
73	  setVisible(element, false);
74	
75	  function open() {
76	    setVisible(element, true);
77	    restartTimer();
78	  }
79	
80	  function close() {
81	    clearTimeout(closeTimerId);
82	    setVisible(element, false);
83	  }
84	
85	  return {
86	    element,
87	    open,
88	    close,
89	    isOpen: () => !element.hidden,
90	    setCharVisible: (isVisible) => {
91	      toggleCharButton.textContent = isVisible
92	        ? MESSAGES.hideCurrentChar
93	        : MESSAGES.showCurrentChar;
94	    },
95	    dispose: () => clearTimeout(closeTimerId),
96	  };
97	}
