1	import { renderQr } from '../platform/qr-view.js';
2	import { shareUrl } from '../platform/share-helper.js';
3	import { createElement, setVisible } from './dom.js';
4	import { MESSAGES } from './messages.js';
5	
6	/**
7	 * @typedef {Object} QrOverlayOptions
8	 * @property {string} closeLabel 閉じるボタンの文言(「戻る」「閉じる」)
9	 * @property {() => void} onClose 閉じるボタンが押されたとき
10	 */
11	
12	/**
13	 * QRコードを白背景で画面いっぱいに表示する。
14	 * 作成画面の「拡大表示」と、参加画面の「QRコードを見せる」で共用する。
15	 *
16	 * @param {HTMLElement} parent 追加先の要素
17	 * @param {string} url QRコードにする共有URL
18	 * @param {QrOverlayOptions} options
19	 * @returns {() => void} 取り除く関数
20	 */
21	export function showQrOverlay(parent, url, options) {
22	  const qrBox = createElement('div', { className: 'qr-overlay__qr' });
23	  const status = createElement('p', {
24	    className: 'qr-overlay__status',
25	    attrs: { role: 'status', 'aria-live': 'polite' },
26	  });
27	  const urlText = createElement('p', {
28	    className: 'share-url',
29	    text: url,
30	  });
31	  setVisible(urlText, false);
32	
33	  const shareButton = createElement('button', {
34	    className: 'button',
35	    text: MESSAGES.share,
36	    attrs: { type: 'button' },
37	    on: {
38	      click: async () => {
39	        const result = await shareUrl(url);
40	        if (result === 'copied') status.textContent = MESSAGES.shareCopied;
41	        if (result === 'failed') {
42	          status.textContent = MESSAGES.shareFailed;
43	          setVisible(urlText, true);
44	        }
45	      },
46	    },
47	  });
48	  const closeButton = createElement('button', {
49	    className: 'button button--primary',
50	    text: options.closeLabel,
51	    attrs: { type: 'button' },
52	    on: { click: () => options.onClose() },
53	  });
54	
55	  const overlay = createElement(
56	    'div',
57	    {
58	      className: 'qr-overlay',
59	      attrs: { role: 'dialog', 'aria-label': MESSAGES.qrSectionLabel },
60	    },
61	    [
62	      qrBox,
63	      status,
64	      urlText,
65	      createElement('div', { className: 'button-row' }, [
66	        shareButton,
67	        closeButton,
68	      ]),
69	    ]
70	  );
71	  renderQr(qrBox, url);
72	  parent.append(overlay);
73	  closeButton.focus();
74	
75	  return () => overlay.remove();
76	}
