1	// 配信物(public/)の転送量(gzip後)の合計が上限以内か検査する。
2	// 会場で大勢が同時に読み込んでも回線が詰まらないようにするため(PRD 非機能要件)。
3	import { readdirSync, readFileSync } from 'node:fs';
4	import { join, relative } from 'node:path';
5	import { gzipSync } from 'node:zlib';
6	
7	const PUBLIC_DIR = new URL('../public/', import.meta.url).pathname;
8	const LIMIT_BYTES = 100 * 1024;
9	
10	/**
11	 * ディレクトリ以下のファイルのパスをすべて集める。
12	 * @param {string} dir ディレクトリ
13	 * @returns {string[]} ファイルのパス
14	 */
15	function listFiles(dir) {
16	  return readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
17	    const path = join(dir, entry.name);
18	    return entry.isDirectory() ? listFiles(path) : [path];
19	  });
20	}
21	
22	const sizes = listFiles(PUBLIC_DIR).map((path) => ({
23	  path: relative(PUBLIC_DIR, path),
24	  gzipBytes: gzipSync(readFileSync(path), { level: 9 }).length,
25	}));
26	sizes.sort((a, b) => b.gzipBytes - a.gzipBytes);
27	const totalBytes = sizes.reduce((sum, file) => sum + file.gzipBytes, 0);
28	
29	for (const file of sizes) {
30	  console.log(
31	    `${(file.gzipBytes / 1024).toFixed(1).padStart(7)} KB  ${file.path}`
32	  );
33	}
34	console.log(
35	  `合計 ${(totalBytes / 1024).toFixed(1)} KB / 上限 ${LIMIT_BYTES / 1024} KB(gzip後)`
36	);
37	
38	if (totalBytes > LIMIT_BYTES) {
39	  console.error('配信物の転送量が上限を超えています');
40	  process.exit(1);
41	}
