1	// 手動確認用に public/ をローカルで配信する(開発時のみ。配信物には含めない)。
2	// 使い方: npm run serve [-- ポート番号]
3	import { createServer } from 'node:http';
4	import { readFile, stat } from 'node:fs/promises';
5	import { extname, join, normalize, sep } from 'node:path';
6	
7	const PUBLIC_DIR = normalize(new URL('../public/', import.meta.url).pathname);
8	const DEFAULT_PORT = 8080;
9	const port = Number(process.argv[2] ?? process.env.PORT ?? DEFAULT_PORT);
10	
11	/** @type {Record<string, string>} */
12	const CONTENT_TYPES = {
13	  '.html': 'text/html; charset=utf-8',
14	  '.js': 'text/javascript; charset=utf-8',
15	  '.css': 'text/css; charset=utf-8',
16	  '.svg': 'image/svg+xml',
17	  '.png': 'image/png',
18	  '.json': 'application/json; charset=utf-8',
19	  '.webmanifest': 'application/manifest+json',
20	};
21	
22	/**
23	 * URLのパスを public/ 内のファイルパスにする。public/ の外を指すなら null。
24	 * @param {string} urlPath リクエストのパス
25	 * @returns {string | null} ファイルパス
26	 */
27	function resolvePath(urlPath) {
28	  const decoded = decodeURIComponent(urlPath.split('?')[0]);
29	  const path = normalize(join(PUBLIC_DIR, decoded));
30	  return path.startsWith(PUBLIC_DIR) || path + sep === PUBLIC_DIR ? path : null;
31	}
32	
33	const server = createServer(async (req, res) => {
34	  let path = resolvePath(req.url ?? '/');
35	  try {
36	    if (path === null) throw new Error('forbidden');
37	    if ((await stat(path)).isDirectory()) path = join(path, 'index.html');
38	    const body = await readFile(path);
39	    res.writeHead(200, {
40	      'Content-Type':
41	        CONTENT_TYPES[extname(path)] ?? 'application/octet-stream',
42	      'Cache-Control': 'no-store',
43	    });
44	    res.end(body);
45	  } catch {
46	    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
47	    res.end('Not Found');
48	  }
49	});
50	
51	server.listen(port, () => {
52	  console.log(`http://localhost:${port}/ で public/ を配信しています`);
53	});
