1	import { describe, it, expect } from 'vitest';
2	import {
3	  currentCycleStart,
4	  nextCycleStart,
5	  stateAt,
6	} from '../../../public/js/core/sync-clock.js';
7	import { buildTimeline } from '../../../public/js/core/timeline.js';
8	import { encodeMessage } from '../../../public/js/core/morse-encoder.js';
9	import { EN_TABLE } from '../../../public/js/core/tables/en.js';
10	
11	// 2026-01-01T00:00:00Z(分の0秒)
12	const MINUTE_START_MS = Date.UTC(2026, 0, 1, 0, 0, 0);
13	const UNIT_MS = 250;
14	// SOS: 34拍 = 8.5秒 → 周期10秒
15	const PERIOD_MS = 10000;
16	const timeline = buildTimeline(encodeMessage('SOS', EN_TABLE));
17	
18	describe('currentCycleStart', () => {
19	  it('周期の途中なら、その周期の開始時刻を返す', () => {
20	    expect(currentCycleStart(MINUTE_START_MS + 12345, 15000)).toBe(
21	      MINUTE_START_MS
22	    );
23	    expect(currentCycleStart(MINUTE_START_MS + 15001, 15000)).toBe(
24	      MINUTE_START_MS + 15000
25	    );
26	  });
27	
28	  it('境界ちょうどなら、その時刻を返す', () => {
29	    expect(currentCycleStart(MINUTE_START_MS, 15000)).toBe(MINUTE_START_MS);
30	  });
31	
32	  it('毎分0秒・15秒・30秒・45秒が周期15秒の開始時刻になる', () => {
33	    for (const offsetSec of [0, 15, 30, 45]) {
34	      const startMs = MINUTE_START_MS + offsetSec * 1000;
35	      expect(currentCycleStart(startMs + 1, 15000)).toBe(startMs);
36	    }
37	  });
38	});
39	
40	describe('nextCycleStart', () => {
41	  it('境界の1ms後なら次の周期の開始時刻を返す', () => {
42	    expect(nextCycleStart(MINUTE_START_MS + 1, PERIOD_MS)).toBe(
43	      MINUTE_START_MS + PERIOD_MS
44	    );
45	  });
46	
47	  it('境界の1ms前なら直後の境界を返す', () => {
48	    expect(nextCycleStart(MINUTE_START_MS - 1, PERIOD_MS)).toBe(
49	      MINUTE_START_MS
50	    );
51	  });
52	
53	  it('境界ちょうどなら現在時刻を返す(即開始)', () => {
54	    expect(nextCycleStart(MINUTE_START_MS, PERIOD_MS)).toBe(MINUTE_START_MS);
55	  });
56	});
57	
58	describe('stateAt', () => {
59	  /** @param {number} nowMs */
60	  const at = (nowMs) =>
61	    stateAt(nowMs, MINUTE_START_MS, timeline, UNIT_MS, PERIOD_MS);
62	
63	  it('開始時刻の1ms前なら待機中を返す', () => {
64	    expect(at(MINUTE_START_MS - 1)).toEqual({
65	      phase: 'waiting',
66	      isOn: false,
67	      charIndex: null,
68	      msToNextStart: 1,
69	    });
70	  });
71	
72	  it('待機中は最初の開始時刻までの残りミリ秒を返す', () => {
73	    expect(at(MINUTE_START_MS - 8000).msToNextStart).toBe(8000);
74	  });
75	
76	  it('周期の開始時刻ちょうどなら即座に点灯する', () => {
77	    expect(at(MINUTE_START_MS)).toEqual({
78	      phase: 'playing',
79	      isOn: true,
80	      charIndex: 0,
81	      msToNextStart: PERIOD_MS,
82	    });
83	  });
84	
85	  it('短点の終わり(1拍後)ちょうどで消灯し、その1ms前は点灯している', () => {
86	    expect(at(MINUTE_START_MS + UNIT_MS - 1).isOn).toBe(true);
87	    expect(at(MINUTE_START_MS + UNIT_MS).isOn).toBe(false);
88	    expect(at(MINUTE_START_MS + UNIT_MS).charIndex).toBeNull();
89	  });
90	
91	  it('長点(2文字目の O)の区間では点灯し、送信中の文字は1になる', () => {
92	    // O の最初の長点は8〜11拍
93	    const state = at(MINUTE_START_MS + 9 * UNIT_MS);
94	    expect(state.isOn).toBe(true);
95	    expect(state.charIndex).toBe(1);
96	  });
97	
98	  it('1周を送り終えた後は次の開始時刻まで消灯したまま待つ', () => {
99	    // 送信は27拍(6750ms)で終わり、周期10秒の残りは消灯
100	    for (const offsetMs of [6750, 8500, 9999]) {
101	      const state = at(MINUTE_START_MS + offsetMs);
102	      expect(state.phase).toBe('playing');
103	      expect(state.isOn).toBe(false);
104	    }
105	    expect(at(MINUTE_START_MS + 9999).msToNextStart).toBe(1);
106	  });
107	
108	  it('次の周期の開始時刻ちょうどで再び点灯する', () => {
109	    expect(at(MINUTE_START_MS + PERIOD_MS).isOn).toBe(true);
110	    expect(at(MINUTE_START_MS + PERIOD_MS - 1).isOn).toBe(false);
111	  });
112	
113	  it('1時間後でも同じ位置で同じ状態になる', () => {
114	    const hourMs = 60 * 60 * 1000;
115	    for (let offsetMs = 0; offsetMs < PERIOD_MS; offsetMs += 50) {
116	      const nowMs = MINUTE_START_MS + offsetMs;
117	      expect(at(nowMs + hourMs)).toEqual(at(nowMs));
118	    }
119	  });
120	
121	  it('参加した時刻にかかわらず、同じ時刻なら同じ状態になる', () => {
122	    const nowMs = MINUTE_START_MS + 60000 + 2600;
123	    const early = stateAt(nowMs, MINUTE_START_MS, timeline, UNIT_MS, PERIOD_MS);
124	    const late = stateAt(
125	      nowMs,
126	      MINUTE_START_MS + 60000,
127	      timeline,
128	      UNIT_MS,
129	      PERIOD_MS
130	    );
131	    expect(late).toEqual(early);
132	  });
133	});
